-- Idempotent seed: public product information + PENDING owner source-review candidates.
-- Never creates active lender_rules. Re-running inserts nothing new (ON CONFLICT DO NOTHING).
INSERT INTO public.lender_products (lender_id, name, product_type, official_url, published_min_amount, published_max_amount, amount_kind, pull_type, research_status, channel_scope, source_verified_on, published_apr_min, published_apr_max, apr_source_url, apr_as_of, product_note)
SELECT l.id, v.name, 'personal_loan', v.url, v.mn, v.mx, 'loan_cash', 'unknown', 'partially_verified', v.scope, DATE '2026-11-16', v.amin, v.amax, v.aurl, v.aasof, v.note
FROM (VALUES
  ('Prosper', 'Prosper Personal Loan', 'https://www.prosper.com/personal-loans', 2000, 50000, 'All channels (consumer product page)', 8.99, 35.99, 'https://www.prosper.com/personal-loans', DATE '2026-11-16', 'Marketed range only; not a guaranteed amount or rate. Note Channel prospectus criteria are attached to the separate Note Channel record, not here.'),
  ('Prosper', 'Prosper Personal Loan — Note Channel (individual borrower)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', NULL, NULL, 'Note Channel, single (individual) borrower only — per 2026-04-30 prospectus. Not all Prosper channels; joint loans differ.', NULL, NULL, NULL, NULL, 'Scoped research record for prospectus criteria. Amounts not stated here.'),
  ('Happy Money', 'Happy Money The Payoff Loan', 'https://happymoney.com/getting-approved', 5000, 50000, 'Consumer product page', 8.95, 35.99, 'https://happymoney.com/getting-approved', DATE '2026-11-16', 'Marketed range only; subject to change; not a guaranteed amount or rate.'),
  ('Wells Fargo', 'Wells Fargo Personal Loan', 'https://www.wellsfargo.com/personal-loans/', 3000, 100000, 'Existing Wells Fargo customers (see checklist)', NULL, NULL, NULL, NULL, 'Marketed range; terms vary by amount. No decision score minimum disclosed.'),
  ('AmeriCU', 'AmeriCU Quick Cash', 'https://www.americu.org/quickcash/', 300, 2000, 'AmeriCU members', NULL, NULL, NULL, NULL, 'Small-dollar member loan; page advertises no credit check and a $20 application fee. Membership eligibility is geographic.'),
  ('AmeriCU', 'AmeriCU Personal Unsecured Loan', 'https://www.americu.org/personal-loans/', 1000, 50000, 'AmeriCU members', NULL, NULL, NULL, NULL, 'Marketed range only. No underwriting criteria recorded yet.')
) AS v(lender, name, url, mn, mx, scope, amin, amax, aurl, aasof, note)
JOIN public.lenders l ON l.name = v.lender
ON CONFLICT (lender_id, name) DO NOTHING;

INSERT INTO public.source_review_candidates (seed_key, product_id, criterion, scope, rule_key, bureau, score_model, lookback_months, threshold, representable, not_enforced_reason, source_title, source_url, source_locator, verified_on)
SELECT v.k, p.id, v.crit, v.scope, v.rk, v.bur, v.model, v.lb, v.th, v.rep, v.why, v.title, v.url, v.loc, DATE '2026-11-16'
FROM (VALUES
  ('prosper_nc_score', 'Prosper Personal Loan — Note Channel (individual borrower)', 'TransUnion FICO 08 score of at least 600', 'Note Channel, single borrower', 'min_score', 'transunion', 'FICO 8', NULL::int, 600::numeric, true, NULL, 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_dti', 'Prosper Personal Loan — Note Channel (individual borrower)', 'Debt-to-income ratio at or below 50%', 'Note Channel, single borrower', 'max_dti_pct', NULL, NULL, NULL, 50, true, NULL, 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_trades', 'Prosper Personal Loan — Note Channel (individual borrower)', 'At least 2 open trades', 'Note Channel, single borrower', 'min_open_tradelines', NULL, NULL, NULL, 2, true, NULL, 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_bk', 'Prosper Personal Loan — Note Channel (individual borrower)', 'No bankruptcy filing within the past 12 months', 'Note Channel, single borrower', 'min_months_since_bankruptcy', NULL, NULL, NULL, 12, true, NULL, 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_inq', 'Prosper Personal Loan — Note Channel (individual borrower)', 'No more than 9 credit bureau inquiries in the past 6 months, after duplicates are removed', 'Note Channel, single borrower', 'max_inquiries', NULL, NULL, 6, 9, false, 'Requires de-duplicated inquiry counts; the report reader does not de-duplicate inquiries yet, so this stays Unknown.', 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_income', 'Prosper Personal Loan — Note Channel (individual borrower)', 'Stated annual income greater than $0', 'Note Channel, single borrower', 'min_annual_income', NULL, NULL, NULL, NULL, false, 'Requirement is strictly greater than zero; the engine only supports at-least thresholds, so it is not mapped.', 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('prosper_nc_joint', 'Prosper Personal Loan — Note Channel (individual borrower)', 'Joint loans use different criteria (at least 1 open trade per applicant, separate DTI handling)', 'Note Channel, JOINT borrowers — not inherited by the individual rules', NULL, NULL, NULL, NULL, NULL, false, 'Joint applications are not modeled; individual rules must not be applied to joint loans.', 'Prosper Prospectus (2026-04-30)', 'https://www.prosper.com/Downloads/Legal/Prosper_Prospectus_2026-04-30.pdf', 'printed page 51'),
  ('happymoney_fico620', 'Happy Money The Payoff Loan', 'FICO score of 620 or higher (FICO version not disclosed)', 'Consumer product page', 'min_score', NULL, NULL, NULL, 620, false, 'The page does not state which FICO version or bureau; mapping it to FICO 8 or any model would be invented.', 'Happy Money — Getting approved', 'https://happymoney.com/getting-approved', NULL),
  ('wf_relationship', 'Wells Fargo Personal Loan', 'Must be an existing Wells Fargo customer with a qualifying consumer product (e.g. account) open at least 12 months', 'Existing customers only', NULL, NULL, NULL, NULL, NULL, false, 'Relationship requirement: a specific qualifying product open 12+ months, not just "banks with Wells Fargo". No questionnaire input tracks this yet. No score minimum is disclosed.', 'Wells Fargo — Personal loan checklist', 'https://www.wellsfargo.com/personal-loans/checklist/', NULL),
  ('americu_qc_membership', 'AmeriCU Quick Cash', 'AmeriCU membership for at least 6 months', 'AmeriCU members', NULL, NULL, NULL, NULL, NULL, false, 'Membership duration is not tracked by the questionnaire yet.', 'AmeriCU — Quick Cash', 'https://www.americu.org/quickcash/', NULL),
  ('americu_qc_deposit', 'AmeriCU Quick Cash', 'Recurring monthly direct deposit into AmeriCU', 'AmeriCU members', NULL, NULL, NULL, NULL, NULL, false, 'Direct deposit is not tracked by the questionnaire yet.', 'AmeriCU — Quick Cash', 'https://www.americu.org/quickcash/', NULL),
  ('americu_qc_age', 'AmeriCU Quick Cash', 'Applicant at least 18 years old', 'AmeriCU members', NULL, NULL, NULL, NULL, NULL, false, 'Age is not collected.', 'AmeriCU — Quick Cash', 'https://www.americu.org/quickcash/', NULL),
  ('americu_qc_nocheck', 'AmeriCU Quick Cash', 'Advertised as no credit check (deposit-history based)', 'AmeriCU members', NULL, NULL, NULL, NULL, NULL, false, 'Informational: no score rule should exist for this product.', 'AmeriCU — Quick Cash', 'https://www.americu.org/quickcash/', NULL)
) AS v(k, product, crit, scope, rk, bur, model, lb, th, rep, why, title, url, loc)
JOIN public.lender_products p ON p.name = v.product
ON CONFLICT (seed_key) DO NOTHING;
